    for i, char in enumerate(paren_string):
        if char == '(':
            count += 1
            if count == 1:
                start = i
        elif char == ')':
            count -= 1
            if count == 0:
                clusters.append(paren_string[start:i+1])

    result = []
    # Step 3: Separate each cluster into distinct strings
    for cluster in clusters:
        result.append(cluster)

    # Step 4: Ensure each cluster is balanced and not nested within each other
    final_result = []
    for cluster in result:
        stack = []
        is_balanced = True
        for char in cluster:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack or stack[-1] != '(':
                    is_balanced = False
                    break
                stack.pop()
        if is_balanced and not stack:
            final_result.append(cluster)

    return final_result

