    # Step 2: Identify the start and end indices of each cluster of nested parentheses
    clusters = []
    start = 0
    stack = []
    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                start = stack.pop()
                clusters.append((start, i))

    # Step 3: Extract each cluster using the identified indices
    distinct_clusters = []
    for start, end in clusters:
        distinct_clusters.append(paren_string[start:end+1])

    # Step 4: Check if each extracted cluster is balanced and not nested within each other
    def is_balanced(cluster):
        stack = []
        for char in cluster:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    final_clusters = [cluster for cluster in distinct_clusters if is_balanced(cluster)]

    # Step 5: Return the list of distinct strings
    return final_clusters

